package org.novasos.healthysv2.consultation;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class ConsultationTests{
 @Test void buildsAndCompletesFullClinicalRecord(){UUID patient=UUID.randomUUID(),professional=UUID.randomUUID();var c=Consultation.start(patient,professional,UUID.randomUUID(),null,null,"GENERAL","Annual check-up");var vital=c.addVitalSign(new BigDecimal("37.2"),new BigDecimal("72"),new BigDecimal("180"),120,80,70,16,new BigDecimal("98"),null,professional);c.addDiagnosis(null,"PRIMARY","Hypertension","ACTIVE");c.addNote(professional,"SOAP","Patient is stable");c.addObservation(professional,"GENERAL","Stable",null,null);c.addTreatment("Lifestyle changes",LocalDate.now(),LocalDate.now().plusDays(30),null);c.addFollowUp(LocalDate.now().plusDays(30),"Control blood pressure",null);c.complete();assertThat(vital.getBmi()).isEqualByComparingTo("22.22");assertThat(c.getStatus()).isEqualTo("COMPLETED");assertThat(c.getCompletedAt()).isNotNull();assertThat(c.getVitalSigns()).hasSize(1);assertThat(c.getDiagnoses()).hasSize(1);assertThat(c.getNotes()).hasSize(1);assertThat(c.getObservations()).hasSize(1);assertThat(c.getTreatments()).hasSize(1);assertThat(c.getFollowUps()).hasSize(1);assertThatThrownBy(()->c.addNote(professional,"SOAP","Late change")).isInstanceOf(IllegalStateException.class);}
 @Test void validatesObservationAndTreatmentDates(){var c=Consultation.start(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,null,"GENERAL",null);assertThatThrownBy(()->c.addObservation(null,"EXAM",null,null,null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->c.addTreatment("Plan",LocalDate.now(),LocalDate.now().minusDays(1),null)).isInstanceOf(IllegalArgumentException.class);}
}
